    for _ in range(samples):
        x, y = random.random(), random.random()
        if x > y:
            x, y = y, x
        l1 = x
        l2 = y - x
        l3 = 1.0 - y
        L_min = min(l1, l2, l3)
        L_max = max(l1, l2, l3)
        if L_min / L_max >= 0.25:
            count += 1
    return count / samples

prob = estimate_probability()
print('WITNESS:', json.dumps({
    "polarity": "positive",
    "data": {"probability": prob, "description": "Estimated probability that L_min/L_max >= 1/4"}
}))
